#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn source_layer_round_trips() {
        let json = serde_json::to_string(&SourceLayer::L5).unwrap();
        let back: SourceLayer = serde_json::from_str(&json).unwrap();
        assert_eq!(back, SourceLayer::L5);
    }
}
